644	def _normalize_set_value(field_name, value):
645	    """校验 set 操作的值并返回最终入库值；非法时抛 BatchUpdateError。
646	
647	    去除前后空白；仅含空白按清空（None）处理；来源/地区/行业保留内部空白与换行；
648	    重要日期非空时须为 YYYY-MM-DD 真实日历日期。
649	    """
650	    if not isinstance(value, str):
651	        raise BatchUpdateError("%s的设置值不是文本" % FIELD_LABELS[field_name])
652	    text = value.strip()
653	    if not text:
654	        return None
655	    if field_name == "important_date":
656	        ok, reason = check_date(text)
