662	def batch_update_clients(database, payload):
663	    """执行批量修改，返回 {"updated_count": 去重后的客户数}；非法请求抛 BatchUpdateError。
664	
665	    任一问题都整次拒绝，不写入任何客户。
666	    """
667	    if not isinstance(payload, dict):
668	        raise BatchUpdateError("请求体必须是 JSON 对象")
669	
670	    raw_ids = payload.get("ids")
671	    if not isinstance(raw_ids, list):
672	        raise BatchUpdateError("ids 必须是客户编号数组")
673	    if not raw_ids:
674	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
675	
676	    ids = []
677	    seen_ids = set()
678	    for raw_id in raw_ids:
679	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
680	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
681	        if raw_id > MAX_CLIENT_ID:
682	            raise BatchUpdateError(
683	                "客户编号超出可接受范围：%d（编号须在 1 到 %d 之间）"
684	                % (raw_id, MAX_CLIENT_ID))
685	        if raw_id not in seen_ids:
686	            seen_ids.add(raw_id)
687	            ids.append(raw_id)
688	
689	    raw_updates = payload.get("updates", {})
690	    if not isinstance(raw_updates, dict):
691	        raise BatchUpdateError("updates 必须是字段修改说明对象")
692	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
693	    if extra:
694	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
695	
696	    actions = {}
697	    for field_name in OPTIONAL_FIELDS:
698	        spec = raw_updates.get(field_name, {"op": "keep"})
699	        if not isinstance(spec, dict):
700	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
701	        op = spec.get("op")
702	        if op not in ("keep", "set", "clear"):
703	            raise BatchUpdateError(
704	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
705	        if op == "keep":
706	            continue
707	        if op == "clear":
708	            actions[field_name] = None
709	        else:
710	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
711	
712	    if not actions:
713	        raise BatchUpdateError("全部字段均保持原值：请至少选择一个字段进行设置或清空")
714	
715	    placeholders = ",".join("?" for _ in ids)
716	    existing = {
717	        row[0]
718	        for row in database.execute(
719	            "SELECT id FROM clients WHERE id IN (%s)" % placeholders, ids
720	        )
721	    }
722	    missing = [cid for cid in ids if cid not in existing]
723	    if missing:
724	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
725	
726	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
727	    params = list(actions.values()) + ids
728	    try:
729	        database.execute(
730	            "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders), params
731	        )
732	        database.commit()
733	    except sqlite3.DatabaseError:
734	        database.rollback()
735	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
736	
737	    return {"updated_count": len(ids)}
