740	def parse_csv(text):
741	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
742	
743	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
744	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
745	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
746	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
747	    - 文件结束时仍有字段处于引号内（引号未闭合）。
748	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
749	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
750	    """
751	    rows = []
752	    record = []
753	    field = []
754	    quoted = False        # 当前字段处于引号内
755	    started = False       # 当前字段已经开始（已有内容或已进入引号）
756	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
757	    record_number = 0     # 0 = 表头，1 起为数据记录
758	    i = 0
759	    n = len(text)
760	
761	    def location():
762	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
763	
764	    def structure_error(kind):
765	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
766	
767	    def finish_record():
768	        nonlocal record, field, started, closed
769	        record.append("".join(field))
770	        rows.append(record)
771	        record = []
772	        field = []
773	        started = False
774	        closed = False
775	
776	    while i < n:
777	        c = text[i]
778	        if quoted:
779	            if c == '"':
780	                if i + 1 < n and text[i + 1] == '"':
781	                    field.append('"')
782	                    i += 2
783	                    continue
784	                quoted = False
785	                closed = True
786	                i += 1
787	                continue
788	            if c == "\r":
789	                # 统一字段内换行符为 LF
790	                if i + 1 < n and text[i + 1] == "\n":
791	                    i += 1
792	                field.append("\n")
793	                i += 1
794	                continue
795	            field.append(c)
796	            i += 1
797	            continue
798	        if closed:
799	            # 引号已结束，只允许逗号、记录换行或文件结束
800	            if c == ",":
801	                record.append("".join(field))
802	                field = []
803	                started = False
804	                closed = False
805	            elif c in "\r\n":
806	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
807	                    i += 1
808	                finish_record()
809	                record_number += 1
810	            else:
811	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
812	            i += 1
813	            continue
814	        if c == '"' and not started:
815	            quoted = True
816	            started = True
817	        elif c == '"':
818	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
819	        elif c == ",":
820	            record.append("".join(field))
821	            field = []
822	            started = False
823	        elif c in "\r\n":
824	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
825	                i += 1
826	            if not started and not record and not field:
827	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
828	                i += 1
829	                continue
830	            finish_record()
831	            record_number += 1
832	        else:
833	            field.append(c)
834	            started = True
835	        i += 1
836	    if quoted:
837	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
838	    if started or field or record or closed:
839	        record.append("".join(field))
840	        rows.append(record)
841	    if not rows:
842	        raise FileError("CSV 内容为空：缺少表头")
843	    return rows[0], rows[1:]
