845	
846	def check_date(value):
847	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
848	    match = DATE_RE.match(value)
849	    if not match:
850	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
851	    try:
852	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
853	    except ValueError:
854	        return False, "重要日期无效（%s）：不是真实日历日期" % value
855	    return True, None
856	
857	
858	def import_clients(database, text):
859	    """执行导入，返回响应字典；文件级错误抛 FileError。"""
860	    header, data_rows = parse_csv(text)
861	    headers = [h.strip() for h in header]
862	
863	    seen = set()
864	    duplicates = []
865	    for h in headers:
866	        if h in seen and h not in duplicates:
867	            duplicates.append(h)
