879	    date_index = index.get("important_date")
880	
881	    existing = {}
882	    for cid, cname in database.execute("SELECT id, name FROM clients"):
883	        existing[(cname or "").strip().casefold()] = cid
884	
885	    imported = []
886	    failures = []
887	    seen_in_file = {}
888	
889	    for row_number, raw in enumerate(data_rows, start=1):
890	        if len(raw) != len(headers):
