962	    args.data_dir.mkdir(parents=True, exist_ok=True)
963	    database = sqlite3.connect(args.data_dir / "client-book.sqlite")
964	    database.execute("CREATE TABLE IF NOT EXISTS clients (id INTEGER PRIMARY KEY, name TEXT NOT NULL)")
965	    columns = {row[1] for row in database.execute("PRAGMA table_info(clients)")}
966	    for field_name in OPTIONAL_FIELDS:
