973	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
974	            self.send_response(status)
975	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
